    MakeWeapon(melee, 10, true, meleeE, 1, &augMelee, 0);
    MakeWeapon(ranged, 20, true, rangedE, 1, 0, 0);
    MakeWeapon(fresh, 30, true, newE, 2, &augNew, &show);
